INSERT INTO public.portfolio_works (id, title, description, image_url, category, display_order, is_featured, created_at, updated_at, media_type, website_url) VALUES
('f0eb58d9-c3d3-49bb-b4de-aaaa77218a95', 'Rahaman Constructions', 'Rahaman Constructions is a leading architectural planning, interior design, and turnkey construction firm based in Agartala, India. The company''s portfolio website displays a comprehensive gallery of completed projects, detailed services from soil testing to modular kitchen design, and an integrated inquiry channel.', 'https://renskjrttadhptrwnobz.supabase.co/storage/v1/object/public/portfolio-images/portfolio/rahaman_constructions.webp', 'Website', 3, true, '2026-06-13T12:45:49.784386+00:00', '2026-06-13T12:45:49.784386+00:00', 'image', 'https://rahamanconstruction.in/'),
('a3d2ef9c-7f1a-4bc2-9dbf-712aa240c824', 'AddMenu', 'AddMenu is a digital QR code menu platform tailored for hotels and restaurants in Tripura, India. It empowers business owners to build contactless menus rapidly, facilitating seamless guest scanning, browsing, and ordering without downloading an external app.', 'https://renskjrttadhptrwnobz.supabase.co/storage/v1/object/public/portfolio-images/portfolio/addmenu.webp', 'Website', 4, true, '2026-06-13T12:45:49.784386+00:00', '2026-06-13T12:45:49.784386+00:00', 'image', 'https://addmenu.in/'),
('643d3ede-a806-47d0-82df-2fd9382a4736', 'Qbuyse', 'Qbuyse is an online local marketplace platform designed to connect buyers and sellers across India for products ranging from electronics to furniture. The platform supports state-wise filtering, localized product listings, and direct communication channels for regional deals.', 'https://renskjrttadhptrwnobz.supabase.co/storage/v1/object/public/portfolio-images/portfolio/qbuyse.webp', 'Website', 7, true, '2026-06-13T12:45:49.784386+00:00', '2026-06-13T12:45:49.784386+00:00', 'image', 'https://www.qbuyse.online/'),
('b768a88a-cc8f-4742-aeb5-f9074a059b6b', 'iD3cor Interio', 'iD3cor Interio is a premium interior design firm based in Agartala, Tripura, specializing in modular kitchens, modern home decor, and customized interior layout design. Its portfolio website serves as an elegant display of its design projects, offering clients a direct look at the firm''s craftsmanship and service options.', 'https://renskjrttadhptrwnobz.supabase.co/storage/v1/object/public/portfolio-images/portfolio/id3cor_interio.webp', 'Website', 6, true, '2026-06-13T12:45:49.784386+00:00', '2026-06-13T12:45:49.784386+00:00', 'image', 'https://id3cor.com/'),
('59341142-59fd-454f-8e4b-820d28e1b7aa', 'Dhristi Services', 'Dhristi is a professional portfolio website for a government contractor in North-East India, offering civil, electrical, mechanical, and telecom engineering services. The website provides details on licensing, certifications, past government projects, and an automated request-a-quote channel.', 'https://renskjrttadhptrwnobz.supabase.co/storage/v1/object/public/portfolio-images/portfolio/dhristi_services.webp', 'Website', 5, true, '2026-06-13T12:45:49.784386+00:00', '2026-06-13T12:45:49.784386+00:00', 'image', 'https://dhristi.co.in/'),
('30445a5c-8206-4929-856b-02ffc16ee6f4', 'Clorefy', 'Clorefy is an AI-powered document generation platform that allows users to create invoices, contracts, and proposals in seconds using plain English prompts. It automatically integrates business details, applies local tax regulations, and inserts active payment links for a streamlined billing workflow.', 'https://renskjrttadhptrwnobz.supabase.co/storage/v1/object/public/portfolio-images/portfolio/clorefy_mockup.webp', 'Website', 1, true, '2026-06-13T12:45:49.784386+00:00', '2026-06-13T12:45:49.784386+00:00', 'image', 'https://clorefy.com/'),
('ee469b8d-588b-4118-b50c-38b450179542', 'The Pink Brasserie', 'The Pink Brasserie is a vibrant restaurant located in Agartala, Tripura, India, offering a premium dining experience. Its website features online reservations, team profiles, career opportunities, and feedback options, providing guests with an engaging digital interface.', 'https://renskjrttadhptrwnobz.supabase.co/storage/v1/object/public/portfolio-images/portfolio/pink_brasserie.webp', 'Website', 2, true, '2026-06-13T12:45:49.784386+00:00', '2026-06-13T12:45:49.784386+00:00', 'image', 'https://www.thepinkbrasserie.com/'),
('8bf4118c-6697-4f51-9d7a-9b42f677cb8a', 'Aura Fine Jewelry', 'Minimalist brand identity and visual design for a premium bespoke jewelry boutique, focusing on delicate line art and gold foil typography.', 'https://renskjrttadhptrwnobz.supabase.co/storage/v1/object/public/portfolio-images/portfolio/jewelry_design.webp', 'Graphics Design', 8, true, '2026-06-13T13:01:56.939984+00:00', '2026-06-13T13:01:56.939984+00:00', 'image', NULL),
('0743c144-ffef-4a99-89de-83e56516a4cc', 'Vanguard Architecture', 'Modernist brand identity and graphic design system for a sustainable architectural studio, utilizing bold structural lines and raw concrete textures.', 'https://renskjrttadhptrwnobz.supabase.co/storage/v1/object/public/portfolio-images/portfolio/architect_design_v2.webp', 'Graphics Design', 9, true, '2026-06-13T13:01:56.939984+00:00', '2026-06-13T13:01:56.939984+00:00', 'image', NULL),
('a4f20f45-1d08-4c22-9423-d40bdd5222cc', 'iD3cor Concept Board', 'Bespoke concept and material board for a luxury modern home, featuring raw oak wood samples, concrete tiles, and minimal brass accents.', 'https://renskjrttadhptrwnobz.supabase.co/storage/v1/object/public/portfolio-images/portfolio/id3cor_concept.webp', 'Graphics Design', 12, true, '2026-06-13T13:28:27.835013+00:00', '2026-06-13T13:28:27.835013+00:00', 'image', NULL),
('d95e96aa-0647-4854-b8be-ef10784725b0', 'iD3cor Brand Identity', 'Minimalist visual identity and stationery design for iD3cor Interio, showcasing luxury warm gray business cards and blind debossed lettering.', 'https://renskjrttadhptrwnobz.supabase.co/storage/v1/object/public/portfolio-images/portfolio/id3cor_branding.webp', 'Graphics Design', 11, true, '2026-06-13T13:28:27.835013+00:00', '2026-06-13T13:28:27.835013+00:00', 'image', NULL),
('1ede5cbc-0f92-4d23-8592-7323633c9118', 'iD3cor Architectural Signage', 'Minimalist outdoor signage design mockup for iD3cor, showcasing a matte black logo on natural travertine stone.', 'https://renskjrttadhptrwnobz.supabase.co/storage/v1/object/public/portfolio-images/portfolio/id3cor_signage.webp', 'Graphics Design', 13, true, '2026-06-13T13:31:22.673291+00:00', '2026-06-13T13:31:22.673291+00:00', 'image', NULL),
('90881dd1-da45-41fa-8331-b0e62edaa12b', 'iD3cor Editorial Lookbook', 'Premium magazine editorial layout and lookbook design for iD3cor''s luxury residential projects.', 'https://renskjrttadhptrwnobz.supabase.co/storage/v1/object/public/portfolio-images/portfolio/id3cor_editorial.webp', 'Graphics Design', 14, true, '2026-06-13T13:31:22.673291+00:00', '2026-06-13T13:31:22.673291+00:00', 'image', NULL),
('e1c4c2e8-2602-484b-baf5-b05ce2c2927d', 'Goodluck interior', 'A rhythmic promotional cut for an interior design firm. Focused on atmospheric pacing, warm lighting accents, and seamless transitions to elevate premium living spaces.', 'https://renskjrttadhptrwnobz.supabase.co/storage/v1/object/public/portfolio-images/portfolio/rosxj20t7b-1781359629813.mp4', 'Video', 999, true, '2026-06-13T14:07:21.104+00:00', '2026-06-13T14:07:21.104+00:00', 'video', NULL),
('9a1a6929-f1a8-4168-a1c3-f8e984b56342', 'Project Progress Reel', 'An engaging real estate edit focused on sharp cuts and precise asset placement, transforming under-construction footage into a high-energy teaser.', 'https://renskjrttadhptrwnobz.supabase.co/storage/v1/object/public/portfolio-images/portfolio/w7u2sw88wzf-1781359829448.mp4', 'Video', 999, false, '2026-06-13T14:10:33.627904+00:00', '2026-06-13T14:10:33.627904+00:00', 'video', NULL),
('82a7e1ca-5871-4186-9024-1b63b67c4de2', 'Design Studio Project Teaser', 'A fast-cut progress reel edited for a modern design studio. Uses rapid-fire framing and rhythmic cuts to turn raw site footage into an engaging brand asset.', 'https://renskjrttadhptrwnobz.supabase.co/storage/v1/object/public/portfolio-images/portfolio/dpyds6zfzd-1781360057651.mp4', 'Video', 999, true, '2026-06-13T14:14:22.344324+00:00', '2026-06-13T14:14:22.344324+00:00', 'video', NULL),
